/** 
 * Releases the current output buffer. If the  {@link MediaCodec} was configured with an outputsurface, setting  {@code render} to {@code true} will first send the buffer to the outputsurface. The surface will release the buffer back to the codec once it is no longer used/displayed. <p>This should be called after the buffer has been processed. The next output buffer will not be available until the previous has been released.
 */
public void releaseOutputBuffer(boolean render){
  outputBuffer = null;
  try {
    mediaCodec.releaseOutputBuffer(outputBufferIndex, render);
  } catch (IllegalStateException e) {
    e.printStackTrace();
  }
  outputBufferIndex = C.INDEX_UNSET;
}
